INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(14301, 'Psalms 86:5', 'Psalms', 86, 5, '&nbsp;تۀ بخښونکے او ښۀ يې مالِکه خُدايه، او څوک چې درنه سوال کوى تۀ د هغوئ سره نۀ ختمېدونکې مينه کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14302, 'Psalms 86:6', 'Psalms', 86, 6, '&nbsp;زما دُعا واوره، اے مالِکه خُدايه، د رحم دپاره زما ژړا واوره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14303, 'Psalms 86:7', 'Psalms', 86, 7, '&nbsp;زما د تکليف په ورځ به زۀ تا ته آواز وکړم، نو تۀ به جواب راکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14304, 'Psalms 86:8', 'Psalms', 86, 8, '&nbsp;اے مالِکه خُدايه، ستا نه بغېر بل خُدائ نشته، ستا په شان کارونه څوک هم کولے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14305, 'Psalms 86:9', 'Psalms', 86, 9, '&nbsp;اے مالِکه خُدايه، ټول قومونه تا پېدا کړى دى، دوئ به راشى او ستا په وړاندې به عبادت وکړى. او دوئ به ستا نوم ته جلال ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14306, 'Psalms 86:10', 'Psalms', 86, 10, '&nbsp;تۀ لوئ يې او ښائسته کارونه کوې. يواځې هم تۀ خُدائ پاک يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14307, 'Psalms 86:11', 'Psalms', 86, 11, '&nbsp;اے مالِکه خُدايه، ما ته خپله لار راوښايه، نو زۀ به ستا په حقيقت کښې وګرځم، مطمئن زړۀ ما له راکړه چې زۀ ستا عزت وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14308, 'Psalms 86:12', 'Psalms', 86, 12, '&nbsp;اے مالِکه، زما پاکه خُدايه، په خپل ټول زړۀ سره به ستا ثناء ادا کړم، زۀ به ستا نوم له د تل دپاره جلال ورکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14309, 'Psalms 86:13', 'Psalms', 86, 13, '&nbsp;ځکه چې زما دپاره ستا مينه ډېره ده، تا زۀ د قبر د کندې نه بچ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14310, 'Psalms 86:14', 'Psalms', 86, 14, '&nbsp;اے پاکه خُدايه، مغروران په ما حملې کوى، د ظالمانو يوه ډله زما ژوند پسې ګرځى، هغه خلق څوک چې ستا عزت نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14311, 'Psalms 86:15', 'Psalms', 86, 15, '&nbsp;خو تۀ، اے مالِکه خُدايه، رحيم او مهربانه يې. په غصه کښې تېزى نۀ کوې او د ډېرې مينې او وفادارۍ نه کار اخلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14312, 'Psalms 86:16', 'Psalms', 86, 16, '&nbsp;ما ته راوګرځه او په ما باندې رحم وکړه، خپل خِدمت کوونکى له طاقت ورکړه، د خپلې وينځې زوئ بچ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14313, 'Psalms 86:17', 'Psalms', 86, 17, '&nbsp;ما ته نښه راوښايه ستا د ښۀ‌والى، نو چې زما دشمنان دا وګورى نو وبه شرميږى، ځکه چې اے مالِکه خُدايه، تا زما مدد وکړو. او ما له دې تسلى راکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14314, 'Psalms 87:1', 'Psalms', 87, 1, '&nbsp;هغۀ د ښار بنياد په مقدس غر باندې لګولے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14315, 'Psalms 87:2', 'Psalms', 87, 2, '&nbsp;د صيون د ښار سره مالِک خُدائ مينه کوى د يعقوب د نورو ښارونو په نسبت ورسره زياته مينه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14316, 'Psalms 87:3', 'Psalms', 87, 3, '&nbsp;ستا په حقله د جلال خبرې شوې دى، اے د خُدائ پاک ښاريې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14317, 'Psalms 87:4', 'Psalms', 87, 4, '&nbsp;څوک چې ما پېژنى زۀ به په هغوئ کښې مِصر او بابل وشمېرم. فلستيه او صور او هم ايتهوپيا. زۀ به دا وايم چې، ”دا هم په صيون کښې پېدا شوى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14318, 'Psalms 87:5', 'Psalms', 87, 5, '&nbsp;خو د صيون په حقله به وئيلے شى، ”هر څوک چې په دې ښار کښې پېدا شوى وُو نو هغه به د دې ښار شمېرلے شى، او خُدائ تعالىٰ به په خپله دې ښاريې له برکت ورکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14319, 'Psalms 87:6', 'Psalms', 87, 6, '&nbsp;مالِک خُدائ به د قومونو په مردم‌شمارۍ کښې داسې وليکى، چې، ”دا دى هغه خلق چې صيون کښې پېدا شوى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14320, 'Psalms 87:7', 'Psalms', 87, 7, '&nbsp;نو خلق به شپيلۍ غږوى او سندرې به وائى، چې، ”صيون د ټولو برکتونو سرچشمه ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14321, 'Psalms 88:1', 'Psalms', 88, 1, '&nbsp;اے مالِکه خُدايه، زما خلاصونکى پاکه خُدايه، شپه او ورځ ستا په وړاندې ژړا کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14322, 'Psalms 88:2', 'Psalms', 88, 2, '&nbsp;زما دُعا دې تا ته درورسيږى، زما ژړا ته غوږ ونيسه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14323, 'Psalms 88:3', 'Psalms', 88, 3, '&nbsp;زما ځان د تکليفونو نه ډک دے، زما ژوند مرګ ته نزدې شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14324, 'Psalms 88:4', 'Psalms', 88, 4, '&nbsp;خلق زما په حقله وائى چې پښې يې په قبر کښې دى. او د يو بې‌وسه کس په شان شوے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14325, 'Psalms 88:5', 'Psalms', 88, 5, '&nbsp;زۀ په مړو کښې حِساب شوے يم، زۀ لکه د مړو په شان شوے يمه چې په قبر کښې پراتۀ وى، څوک چې به تۀ نور نۀ يادوې، څوک چې ستا د نظر نه اخوا شوے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14326, 'Psalms 88:6', 'Psalms', 88, 6, '&nbsp;زۀ دې د قبر کندې ته غورزولے يم، تا زۀ تور تيارو ته غورزولے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14327, 'Psalms 88:7', 'Psalms', 88, 7, '&nbsp;ستا غضب په ما بار شوے دے، او ستا ټولو چپو زۀ رالاندې کړے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14328, 'Psalms 88:8', 'Psalms', 88, 8, '&nbsp;تا زما دوستان ما نه لرې کړى دى، زۀ دې د هغوئ دپاره کرکژن وګرځولم. ګېر يمه زۀ چرته تښتېدلے نۀ شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14329, 'Psalms 88:9', 'Psalms', 88, 9, '&nbsp;زما د ډېره غمه نظر کم شولو. هره ورځ تا ته زارى کوم مالِکه خُدايه، او خپل لاس تا ته د دُعا دپاره اوچتوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14330, 'Psalms 88:10', 'Psalms', 88, 10, '&nbsp;تۀ د مړو دپاره معجزې کوې څۀ؟ څوک چې مړۀ دى دوئ پاڅېدے شى چې ستا ثناء صِفت وکړى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14331, 'Psalms 88:11', 'Psalms', 88, 11, '&nbsp;ولې ستا د ابدى مينې بيان قبر کښې کېدے شى څۀ، يا ستا د وفادارۍ بيان په قبر کښې کېدے شى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14332, 'Psalms 88:12', 'Psalms', 88, 12, '&nbsp;ولې په تيارۀ کښې ستا معجزې پېژندے شى څۀ، يا د فنا په مُلک کښې ستا رښتينوالے څوک پېژندے شى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14333, 'Psalms 88:13', 'Psalms', 88, 13, '&nbsp;خو زۀ مالِکه خُدايه د مدد دپاره تا ته ژړا کوم، زۀ به هر سحر تا ته سوال زارى کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14334, 'Psalms 88:14', 'Psalms', 88, 14, '&nbsp;ولې مالِکه خُدايه تا زۀ رد کړے يم، او ولې تۀ خپل مخ ما نه اړوې څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14335, 'Psalms 88:15', 'Psalms', 88, 15, '&nbsp;زۀ د ځوانۍ نه کړېدلے او مرګ ته رانزدې شوے يم. ما ستا يره تيره کړله او پرېشانه شوے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14336, 'Psalms 88:16', 'Psalms', 88, 16, '&nbsp;ستا قهر په ما باندې راپرېوتے دے، زۀ ستا د يرې نه تباه شوے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14337, 'Psalms 88:17', 'Psalms', 88, 17, '&nbsp;ټوله ورځ لکه د سېلاب په شان رانه راتاو وى، په پوره توګه هغۀ زۀ راګېر کړے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14338, 'Psalms 88:18', 'Psalms', 88, 18, '&nbsp;تا زما محبوب او دوستان رانه جدا کړى دى، تورو تيارو سره مې يارانه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14339, 'Psalms 89:1', 'Psalms', 89, 1, '&nbsp;زۀ به د تل دپاره د مالِک خُدائ د ابدى مينې سندرې وايم، او ستا د وفادارۍ په حقله به وړو او زړو ته ووايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14340, 'Psalms 89:2', 'Psalms', 89, 2, '&nbsp;زۀ به دا بيان کوم چې، ”ستا ابدى مينه به د تل دپاره پاتې وى، ستا وفادارى به د آسمان په شان قائمه وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14341, 'Psalms 89:3', 'Psalms', 89, 3, '&nbsp;مالِک خُدائ وفرمائيل، ”ما د خپل غوره شوى خِدمتګار داؤد سره لوظ وکړو، ما د خپل خِدمتګار داؤد سره دا قسم وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14342, 'Psalms 89:4', 'Psalms', 89, 4, '&nbsp;زۀ به ستا بچى د تل دپاره بادشاهان مقرر کړم، زۀ به ستا تخت نسل در نسل قائم ساتم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14343, 'Psalms 89:5', 'Psalms', 89, 5, '&nbsp;ټول آسمانونه به ستا په لويو معجزو مالِکه خُدايه ثناء ووائى، ستا د فرښتو جماعت به ستا وفادارى ستائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14344, 'Psalms 89:6', 'Psalms', 89, 6, '&nbsp;په ټولو آسمانونو کښې داسې بل څوک نشته لکه د مالِک خُدائ په شان، په آسمانى مخلوق کښې څوک داسې نشته لکه د مالِک خُدائ په شان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14345, 'Psalms 89:7', 'Psalms', 89, 7, '&nbsp;د فرښتو جماعت هم د خُدائ پاک نه يريږى، او د هغۀ شان او شوکت هم د هغه چا نه زيات دے څوک چې ټول د هغۀ د تخت نه ګېرچاپېره راټول شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14346, 'Psalms 89:8', 'Psalms', 89, 8, '&nbsp;اے مالِکه خُدايه، ربُ الافواج خُدايه ستا نه هم څوک زورَور شته څۀ؟ تۀ په پوره ډول سره مالِکه خُدايه وفادار يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14347, 'Psalms 89:9', 'Psalms', 89, 9, '&nbsp;تۀ په غړمبېدونکو سمندرونو بادشاهى کوې، او تۀ د هغوئ چپې او موجونه آراموې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14348, 'Psalms 89:10', 'Psalms', 89, 10, '&nbsp;تا د سمندر بلا ووهله او هغه دې چخڼى کړه، تا خپل دشمنان په خپلو قوى مټو سره خوارۀ وارۀ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14349, 'Psalms 89:11', 'Psalms', 89, 11, '&nbsp;آسمانونه ستا دى او زمکه ستا ده. دُنيا او په دې کښې هر يو څيز تا پېدا کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14350, 'Psalms 89:12', 'Psalms', 89, 12, '&nbsp;شمال دے کۀ جنوب تا پېدا کړے دے. تبور او حرمون په خوشحالۍ سره ستا د نوم ثناء صِفت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14351, 'Psalms 89:13', 'Psalms', 89, 13, '&nbsp;ستا لاس کښې زور دے، ستا لاسونه قوى دى ستا ښے لاس لوئ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14352, 'Psalms 89:14', 'Psalms', 89, 14, '&nbsp;صداقت او عدالت ستا د تخت بنياد دے. مينه او وفادارى ستا د وړاندې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14353, 'Psalms 89:15', 'Psalms', 89, 15, '&nbsp;بختور دى هغوئ څوک چې ستا د خوشحالۍ آواز پېژنى او ستا ثناء صِفت کوى، اے مالِکه خُدايه، څوک چې ستا د حضور په نُور کښې قدم اوچتوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14354, 'Psalms 89:16', 'Psalms', 89, 16, '&nbsp;دوئ ټوله ورځ ستا په نوم خوشحالى کوى، ستا په صداقت فخر کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14355, 'Psalms 89:17', 'Psalms', 89, 17, '&nbsp;تۀ په خپله د دوئ جلال او طاقت يې. او تۀ په خپلې رضامندۍ سره مونږ ته طاقت راکوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14356, 'Psalms 89:18', 'Psalms', 89, 18, '&nbsp;بې‌شکه مالِک خُدائ زمونږ ډال او ساتونکے دے، د بنى اِسرائيلو مقدس ذات زمونږ بادشاه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14357, 'Psalms 89:19', 'Psalms', 89, 19, '&nbsp;يو ځل تا په رويا کښې خپلو وفادارو خلقو ته وفرمائيل او خبرې دې وکړې او ودې فرمائيل، ”ما يو جنګيالى ته طاقت ورکړو، ما د خلقو نه يو ځوان سړے غوره کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14358, 'Psalms 89:20', 'Psalms', 89, 20, '&nbsp;ما خپل خِدمتګار داؤد پېدا کړو. ما هغه په خپلو پاکو تېلو سره غوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14359, 'Psalms 89:21', 'Psalms', 89, 21, '&nbsp;زۀ به په خپل لاس د هغۀ مدد کوم، بې‌شکه چې زما لاس به هغۀ ته طاقت ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14360, 'Psalms 89:22', 'Psalms', 89, 22, '&nbsp;د هغۀ دشمن به هغۀ ته شکست نۀ شى ورکولے، بدکاران به هغۀ ته تکليف نۀ شى رسولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14361, 'Psalms 89:23', 'Psalms', 89, 23, '&nbsp;زۀ به د هغۀ دشمنان د دۀ په مخکښې چخڼى کړم، زۀ به د هغۀ مخالفين سر د لاندې راګزار کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14362, 'Psalms 89:24', 'Psalms', 89, 24, '&nbsp;زما وفادارى او ابدى مينه به د هغۀ سره وى، او زما د نوم په وسيله به د هغۀ مقام اوچت شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14363, 'Psalms 89:25', 'Psalms', 89, 25, '&nbsp;زۀ به د هغۀ لاس تر سمندره پورې اوږد کړم، زۀ به د هغۀ ښى لاس له په ټولو سيندونو اختيار ورکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14364, 'Psalms 89:26', 'Psalms', 89, 26, '&nbsp;هغه به ما ته آواز وکړى چې، ”تۀ يې پلار زما، تۀ زما خُدائ پاک او د خلاصون ګټ يې زما.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14365, 'Psalms 89:27', 'Psalms', 89, 27, '&nbsp;زۀ به هم هغه خپل مشر زوئ مقرر کړم، او هغه به په دُنيا کښې د ټولو بادشاهانو نه اوچت کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14366, 'Psalms 89:28', 'Psalms', 89, 28, '&nbsp;زۀ به تر ابده خپله مينه د هغۀ سره ساتم، زۀ به خپل لوظ د هغۀ سره کله هم نۀ ختموم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14367, 'Psalms 89:29', 'Psalms', 89, 29, '&nbsp;زۀ به تر ابده د هغۀ نسل قائم ساتم، ترڅو چې آسمانونه وى تر هغې به د هغۀ تخت ساتم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14368, 'Psalms 89:30', 'Psalms', 89, 30, '&nbsp;کۀ چرې د هغۀ نسل زما د شريعت نه سرکشى وکړى او زما د حُکمونو په مطابق عمل ونۀ کړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14369, 'Psalms 89:31', 'Psalms', 89, 31, '&nbsp;کۀ چرې دوئ زما قانون مات کړى زما د حُکمونو په ساتلو کښې ناکامه شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14370, 'Psalms 89:32', 'Psalms', 89, 32, '&nbsp;نو زۀ به بيا د دوئ د ګناهونو په وجه دوئ ته په چوکې سره سزا ورکړم، او د دوئ د ګناهونو په وجه به دوئ ته په کوړو سزا ورکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14371, 'Psalms 89:33', 'Psalms', 89, 33, '&nbsp;خو زۀ به خپله ابدى مينه د هغۀ سره ختمه نۀ کړم، او نۀ به کله هم ورسره بې‌وفائى وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14372, 'Psalms 89:34', 'Psalms', 89, 34, '&nbsp;زۀ به کله هم خپل لوظ مات نۀ کړم او نۀ به کله هم د خپلې ژبې بيان نه واوړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14373, 'Psalms 89:35', 'Psalms', 89, 35, '&nbsp;ما يو ځل د تل دپاره په خپل پاکوالى قسم کړے دے، زۀ به داؤد ته دروغ نۀ وايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14374, 'Psalms 89:36', 'Psalms', 89, 36, '&nbsp;د هغۀ د نسل سلسله به هيڅکله نۀ ختميږى. زما په وړاندې به د هغۀ تخت لکه د نمر په شان قائم وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14375, 'Psalms 89:37', 'Psalms', 89, 37, '&nbsp;دا به د سپوږمۍ په شان تر ابده قائم وى، کومه چې به په آسمان کښې د وفا ګواهى ورکوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14376, 'Psalms 89:38', 'Psalms', 89, 38, '&nbsp;خو اوس تا خپل غوره شوى رد کړى او شړلى دى، او خپل غوره شوى بادشاه ته ډېر په قهر شوے يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14377, 'Psalms 89:39', 'Psalms', 89, 39, '&nbsp;تا د خپل خِدمتګار سره لوظ مات کړے دے، او تاج دې ورته په خاورو کښې لاندې غورزولے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14378, 'Psalms 89:40', 'Psalms', 89, 40, '&nbsp;تا د هغۀ ټول دېوالونه کنډر کړى دى، او تا يې ټولې قلعه ګانې تباه کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14379, 'Psalms 89:41', 'Psalms', 89, 41, '&nbsp;خوشې لارَوو هغه تالا والا کړو، او هغه د خپلو ګاونډيانو د خندا شولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14380, 'Psalms 89:42', 'Psalms', 89, 42, '&nbsp;تا د هغۀ د دشمنانو لاس په هغۀ اوچت کړے دے، تا په هغۀ باندې ټول دشمنان خوشحاله کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14381, 'Psalms 89:43', 'Psalms', 89, 43, '&nbsp;هغۀ له دې د تُورې خولۀ پڅه کړې ده، او په جنګ کښې دې د هغۀ ملګرتيا کړې نۀ ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14382, 'Psalms 89:44', 'Psalms', 89, 44, '&nbsp;تا د هغۀ شان او شوکت ختم کړے دے، او د هغۀ تخت دې زمکې ته غورزولے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14383, 'Psalms 89:45', 'Psalms', 89, 45, '&nbsp;تا د هغۀ د ځوانۍ عُمر لنډ کړے دے، تا هغه په شرمونو شرمولے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14384, 'Psalms 89:46', 'Psalms', 89, 46, '&nbsp;اے مالِکه خُدايه، تر کومې پورې به داسې وى؟ آيا تۀ به تر ابده خپل ځان پټوې؟ تر کومې پورې به خپل قهر او غضب لکه د اور بلوې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14385, 'Psalms 89:47', 'Psalms', 89, 47, '&nbsp;راياد کړه تۀ چې زما ژوند به څومره لنډ وى، مونږ ټول مخلوق دې څومره فانى پېدا کړى يُو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14386, 'Psalms 89:48', 'Psalms', 89, 48, '&nbsp;کوم انسان به د تل دپاره ژوندے وى چې مرګ به ونۀ ګورى، او څنګه به خپل ځان د قبر د طاقت نه خلاصوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14387, 'Psalms 89:49', 'Psalms', 89, 49, '&nbsp;مالِکه خُدايه ستا پخوانۍ لويه مينه څۀ شوه، کوم چې تا په خپله وفادارۍ کښې د داؤد سره لوظ کړے وو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14388, 'Psalms 89:50', 'Psalms', 89, 50, '&nbsp;راپه ياد کړه، مالِکه خُدايه چې ستا خِدمتګار څومره د خندا شوے وو، او چې هغه د قومونو پيغورونه به ما څنګه په خپل زړۀ کښې برداشت کول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14389, 'Psalms 89:51', 'Psalms', 89, 51, '&nbsp;په کومو پيغورونو چې مالِکه خُدايه ستا دشمنانو ما پورې وخندل، په کومو چې دوئ په هر قدم کښې ستا د مسح شوى پورې وخندل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14390, 'Psalms 89:52', 'Psalms', 89, 52, '&nbsp;ثناء صِفت دې تر ابده پورې د مالِک خُدائ وى. آمين ثُمه آمين.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14391, 'Psalms 90:1', 'Psalms', 90, 1, '&nbsp;اے مالِکه او پاکه خُدايه، تۀ همېشه زمونږ د اوسېدو ځائ يې، نسل در نسله پورې يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14392, 'Psalms 90:2', 'Psalms', 90, 2, '&nbsp;د دې نه مخکښې چې لا دې غرونه ‎پېدا کړى نۀ وُو او نۀ دې لا زمکه او دُنيا پېدا کړې وه، تۀ خُدائ پاک يې د ازل نه تر ابده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14393, 'Psalms 90:3', 'Psalms', 90, 3, '&nbsp;تۀ بيا بنى آدم د خاورو سره خاورې کړې، ورته ووائې چې، ”اے فانى انسانه واپس خاورې شه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14394, 'Psalms 90:4', 'Psalms', 90, 4, '&nbsp;ځکه ستا په نظر کښې زر کاله داسې دى لکه يوه ورځ چې تېره شوې وى، او يا د شپې يو پار چې تير شوے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14395, 'Psalms 90:5', 'Psalms', 90, 5, '&nbsp;تۀ انسان د مرګ په خوب اودۀ کوې. او دوئ لکه د تازه ګياه په شان په سحر کښې راټوکيږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14396, 'Psalms 90:6', 'Psalms', 90, 6, '&nbsp;په سحر کښې راټوکيږى او تازه وى، په ماښام کښې مړاوى شى او اوچ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14397, 'Psalms 90:7', 'Psalms', 90, 7, '&nbsp;ستا غصې مونږ ختم کړى يُو، او مونږ ستا قهر وارخطا کړى يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14398, 'Psalms 90:8', 'Psalms', 90, 8, '&nbsp;زمونږ ګناهونه دې په خپل مخکښې اېښى دى، زمونږ پټې خطاګانې تا ته ښکاره دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14399, 'Psalms 90:9', 'Psalms', 90, 9, '&nbsp;زمونږ ژوند ستا په قهر کښې تېر شو، زمونږ ژوند په اهونو کښې ختم شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14400, 'Psalms 90:10', 'Psalms', 90, 10, '&nbsp;زمونږ د ژوند موده اويا کاله وى، او کۀ مونږ طاقت ولرُو نو اتيا کاله به وى. خو دا ټول په خفګان او تکليفونو تېروو. او دا زر تېريږى او مونږ ترې نه فنا کيږُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');